package mrpapermoon.whisper.ui.componentimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.shape.CircleShapeimport androidx.compose.material.Iconimport androidx.compose.runtime.Composableimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.graphics.toArgbimport androidx.compose.ui.res.painterResourceimport androidx.compose.ui.tooling.preview.Previewimport androidx.compose.ui.unit.Dpimport androidx.compose.ui.unit.dpimport mrpapermoon.whisper.Rimport mrpapermoon.whisper.entity.UserIconimport mrpapermoon.whisper.entity.Whispererimport mrpapermoon.whisper.ui.theme.WhisperTheme@Composablefun RoundedUserIcon(	whisperer: Whisperer,	modifier: Modifier = Modifier,	size: Dp = 48.dp,) {	val backgroundColor = Color(whisperer.color)	val iconResId = R.drawable.hearing_24dp_1f1f1f_fill0_wght400_grad0_opsz24	Box(		modifier = modifier			.size(size)			.clip(CircleShape)			.background(backgroundColor),		contentAlignment = Alignment.Center,	) {		Icon(			painter = painterResource(id = iconResId),			contentDescription = whisperer.name,			modifier = Modifier.size(size * 0.55f),			tint = Color.White,		)	}}@Preview@Composablefun RoundedUserIconPreview() {	WhisperTheme {		RoundedUserIcon(			whisperer = Whisperer(id = "1", karma = 10, name = "Alice", color = Color.Cyan.toArgb(), icon = UserIcon.EAR)		)	}}